// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint public previousPot;

    function setUp() public {
        c = new C();
        previousPot = 0;
    }

    function testFuzz_property(uint amount1, uint amount2) public {
        vm.assume(amount1 % 10 == 0);
        vm.assume(amount2 % 10 == 0);
        vm.assume(amount1 >= 10);
        vm.assume(amount2 >= 10);

        // First sequence: player1 puts in amount1 (must be multiple of 10)
        address player1 = address(0x1234);
        vm.deal(player1, amount1);
        vm.prank(player1);
        c.play{value: 10}();
        uint potAfterFirst = c.pot();
        // If first play didn't win, pot should equal 10
        if (potAfterFirst != 0) {
            assertTrue(potAfterFirst == 10);
        }

        // Second sequence: player2 puts in amount2
        address player2 = address(0x5678);
        vm.deal(player2, amount2);
        vm.prank(player2);
        c.play{value: 10}();
        uint potAfterSecond = c.pot();
        // If second play didn't win, pot should equal previous pot + 10 (accumulated, not just 10)
        if (potAfterSecond != 0) {
            assertTrue(potAfterSecond == potAfterFirst + 10);
        }
    }
}

